{
  "sql": "SELECT DISTINCT m.chembl_id AS chembl_id, m.pref_name AS pref_name, cs.canonical_smiles AS canonical_smiles, di.mesh_id AS indication_curie, di.mesh_heading AS indication_label, di.max_phase_for_ind AS max_phase_for_ind FROM molecule_dictionary m JOIN drug_indication di ON m.molregno = di.molregno LEFT JOIN compound_structures cs ON m.molregno = cs.molregno WHERE di.max_phase_for_ind = 4 AND di.mesh_id IS NOT NULL AND di.mesh_heading IS NOT NULL AND m.therapeutic_flag = 1;"
}
